package cn.balltv.portal;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;

public class PortalActivity extends Activity {
    JSONArray sites;LinearLayout root,rows;String filter="全部",query=""; boolean active;
    public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);sites=Store.load(this);render();}
    public void onResume(){super.onResume();active=true;} public void onPause(){active=false;super.onPause();}
    void render(){root=Ui.column(this);root.setPadding(Ui.dp(this,24),Ui.dp(this,18),Ui.dp(this,24),Ui.dp(this,12));root.setBackgroundColor(Ui.BG);setContentView(root);
        root.addView(Ui.text(this,"看球入口 TV",30,Color.WHITE));root.addView(Ui.text(this,"选入口 · 找赛事 · 大屏看球      Android 4.4+  /  v0.1",15,Ui.MUTED));
        HorizontalScrollView hs=new HorizontalScrollView(this);LinearLayout bar=new LinearLayout(this);hs.addView(bar);root.addView(hs);
        for(final String s:new String[]{"全部","收藏","最近","第三方","补充"})bar.addView(Ui.button(this,(filter.equals(s)?"● ":"")+s,v->{filter=s;render();}));
        bar.addView(Ui.button(this,"搜索",v->search()));bar.addView(Ui.button(this,"添加",v->edit(-1)));bar.addView(Ui.button(this,"管理 / 帮助",v->settings()));
        ScrollView scroll=new ScrollView(this);rows=Ui.column(this);scroll.addView(rows);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        int count=0;LinearLayout row=null; java.util.ArrayList<Integer> order=new java.util.ArrayList<Integer>();for(int i=0;i<sites.length();i++)order.add(i);
        if(filter.equals("最近"))java.util.Collections.sort(order,(a,b)->Long.compare(getPreferences(0).getLong(sites.optJSONObject(b).optString("id"),0),getPreferences(0).getLong(sites.optJSONObject(a).optString("id"),0)));
        for(final int i:order){final JSONObject o=sites.optJSONObject(i);String id=o.optString("id");if(filter.equals("收藏")&&!Store.fav(this,id))continue;if(filter.equals("最近")&&getPreferences(0).getLong(id,0)==0)continue;
            if((filter.equals("第三方")||filter.equals("补充"))&&!filter.equals(o.optString("group")))continue;if(!(o.optString("name")+o.optString("tags")).toLowerCase(java.util.Locale.ROOT).contains(query.toLowerCase(java.util.Locale.ROOT)))continue;
            if(count%3==0){row=new LinearLayout(this);rows.addView(row);}Button card=Ui.button(this,(Store.fav(this,id)?"★ ":"")+o.optString("name")+"\n"+o.optString("tags","综合赛事")+"\n"+o.optString("status","待实测"),v->details(i));card.setTextSize(18);card.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);card.setMinHeight(Ui.dp(this,112));card.setOnLongClickListener(v->{details(i);return true;});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,Ui.dp(this,124),1);lp.setMargins(5,5,5,5);row.addView(card,lp);count++;}
        if(row!=null)while(row.getChildCount()<3)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));
        if(count==0)rows.addView(Ui.text(this,"暂无入口。可添加网址，或在管理中导入 JSON。",20,Ui.MUTED));
        root.addView(Ui.text(this,"方向键选择 · 确定打开 · 网页内菜单键切换鼠标 · "+count+" 个入口"+(query.length()>0?" · 搜索："+query:""),14,Ui.MUTED));}
    void search(){final EditText t=new EditText(this);t.setSingleLine();t.setText(query);t.setHint("站名或项目：足球 / 篮球 / 网球…");new AlertDialog.Builder(this).setTitle("搜索入口").setView(t).setPositiveButton("搜索",(d,w)->{query=t.getText().toString().trim();render();}).setNeutralButton("清空",(d,w)->{query="";render();}).setNegativeButton("取消",null).show();}
    void details(final int index){final JSONObject o=sites.optJSONObject(index);final JSONArray urls=o.optJSONArray("urls");java.util.ArrayList<String> labels=new java.util.ArrayList<String>();for(int j=0;j<urls.length();j++)labels.add("打开线路 "+(j+1)+"  "+urls.optString(j));labels.add(Store.fav(this,o.optString("id"))?"取消收藏":"加入收藏");labels.add("编辑入口");labels.add("删除入口");labels.add("查看来源与说明");
        new AlertDialog.Builder(this).setTitle(o.optString("name")).setItems(labels.toArray(new String[0]),(d,k)->{if(k<urls.length()){getPreferences(0).edit().putLong(o.optString("id"),System.currentTimeMillis()).apply();Intent intent=new Intent(this,"video".equals(o.optString("type"))?VideoActivity.class:BrowserActivity.class);intent.putExtra("url",urls.optString(k));intent.putExtra("name",o.optString("name"));startActivity(intent);}else if(k==urls.length()){Store.toggle(this,o.optString("id"));render();}else if(k==urls.length()+1)edit(index);else if(k==urls.length()+2)new AlertDialog.Builder(this).setMessage("删除这个入口？").setPositiveButton("删除",(x,y)->{JSONArray a=new JSONArray();for(int j=0;j<sites.length();j++)if(j!=index)a.put(sites.opt(j));sites=a;Store.save(this,sites);render();}).setNegativeButton("取消",null).show();else Ui.message(this,"来源与说明",o.optString("note")+"\n\n来源："+o.optString("source")+"\n检索日期："+o.optString("checked","用户添加")+"\n\n页面可访问不代表直播可播放。");}).setNegativeButton("返回",null).show();}
    void edit(final int index){final JSONObject old=index<0?null:sites.optJSONObject(index);LinearLayout box=Ui.column(this);box.setPadding(24,8,24,8);final EditText name=new EditText(this),urls=new EditText(this),tags=new EditText(this);name.setHint("入口名称");urls.setHint("http/https 网址，每行一个（可粘贴）");urls.setInputType(1|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);tags.setHint("标签：足球 篮球 综合");final CheckBox video=new CheckBox(this);video.setText("这是视频直链（用系统播放器）");box.addView(name);box.addView(urls);box.addView(tags);box.addView(video);
        if(old!=null){name.setText(old.optString("name"));tags.setText(old.optString("tags"));StringBuilder s=new StringBuilder();JSONArray a=old.optJSONArray("urls");for(int i=0;i<a.length();i++)s.append(a.optString(i)).append("\n");urls.setText(s.toString().trim());video.setChecked("video".equals(old.optString("type")));}
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle(index<0?"添加入口":"编辑入口").setView(box).setPositiveButton("保存",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{JSONObject o=old==null?new JSONObject():new JSONObject(old.toString());o.put("id",old==null?"custom-"+java.util.UUID.randomUUID():old.optString("id"));o.put("name",name.getText().toString().trim());JSONArray a=new JSONArray();for(String u:urls.getText().toString().split("\\s+"))if(u.trim().length()>0)a.put(u.trim());o.put("urls",a);o.put("type",video.isChecked()?"video":"web");o.put("tags",tags.getText().toString());if(old==null){o.put("group","第三方");o.put("status","自定义 · 待实测");}Store.validate(new JSONArray().put(o).toString());if(index<0)sites.put(o);else sites.put(index,o);Store.save(this,sites);dialog.dismiss();render();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}));dialog.show();}
    void settings(){new AlertDialog.Builder(this).setTitle("管理 / 帮助").setItems(new String[]{"使用帮助与兼容性","导入本地 JSON（替换入口）","导出入口 JSON","恢复内置入口"},(d,k)->{if(k==0)Ui.message(this,"使用帮助","首页方向键选择入口，确定后选线路。网页内按菜单键切换遥控鼠标：方向键移动，确定点击；在边缘继续移动可滚屏。返回键先退出鼠标或全屏，再返回网页，最后回首页。工具栏可刷新、滚屏、切换桌面模式及外部浏览器。\n\n支持 Android 4.4 / API 19 起安装；网页与视频仍依赖盒子的 WebView、TLS、解码器及站点实现。黑屏可换线路或外部浏览器。不会绕过登录、付费或加密。\n\n导入会替换入口列表；可先导出备份。无需账号，没有统计 SDK。");else if(k==1){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,10);}catch(Exception e){Ui.message(this,"无法打开文件","设备没有文件选择器，可在添加入口中手动输入网址。");}}else if(k==2){try{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"balltv-sites.json");startActivityForResult(i,11);}catch(Exception e){Ui.message(this,"无法导出","设备没有文件选择器。");}}else new AlertDialog.Builder(this).setMessage("恢复内置列表？自定义入口将被替换。").setPositiveButton("恢复",(x,y)->{getSharedPreferences("tv",0).edit().remove("sites").apply();sites=Store.load(this);render();}).setNegativeButton("取消",null).show();}).show();}
    protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;final android.net.Uri uri=data.getData();new Thread(()->{try{if(r==10){final JSONArray a=Store.validate(Store.read(getContentResolver().openInputStream(uri)));runOnUiThread(()->{if(isFinishing())return;new AlertDialog.Builder(this).setMessage("替换为 "+a.length()+" 个入口？").setPositiveButton("导入",(d,w)->{sites=a;Store.save(this,a);render();}).setNegativeButton("取消",null).show();});}else if(r==11){OutputStream out=getContentResolver().openOutputStream(uri,"wt");try{out.write(sites.toString(2).getBytes("UTF-8"));}finally{out.close();}runOnUiThread(()->Toast.makeText(this,"导出成功",Toast.LENGTH_SHORT).show());}}catch(final Exception e){runOnUiThread(()->Ui.message(this,"文件操作失败",e.getMessage()));}}).start();}
}


